import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Introduction: make your place in a living world","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md"}'),r={name:"en/guide/introduction.md"};function o(l,e,s,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<p><span id="introduction-a-living-world-shaped-by-its-people"></span><span id="a-world-that-can-change-your-plans"></span><span id="combat-with-room-to-grow"></span><span id="knowledge-is-useful-in-the-moment"></span><span id="crafts-belong-to-adventurers"></span><span id="discover-your-specialty"></span><span id="magic-is-learned-and-prepared"></span><span id="items-with-a-story"></span><span id="more-than-one-endgame"></span></p><h1 id="introduction-make-your-place-in-a-living-world" tabindex="-1">Introduction: make your place in a living world <a class="header-anchor" href="#introduction-make-your-place-in-a-living-world" aria-label="Permalink to &quot;Introduction: make your place in a living world&quot;">​</a></h1><p><strong>Status:</strong> Proposed direction with Accepted foundations · Features described here may not yet be available.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Build a character through <a href="/Syrolands-Public/en/guide/characters/skills.html">skills</a>, discoveries and the choices you make in the world.</li><li>Fight with manual <a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Modern</a> timing or familiar <a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Legacy</a> auto-attacks; knowledge helps you choose.</li><li>Crafting, magic, trade and exploration offer ambitions beyond a single combat ladder.</li></ul><p>Syrolands reimagines the Ultima Online sandbox around three ideas: the world should react to players, knowledge should matter, and player execution should matter alongside character skill. You can follow these ideas without having played UO.</p><h2 id="coming-from-ultima-online" tabindex="-1">Coming from Ultima Online? <a class="header-anchor" href="#coming-from-ultima-online" aria-label="Permalink to &quot;Coming from Ultima Online?&quot;">​</a></h2><p>These comparisons describe familiar UO traditions, not every expansion or shard. Later weapon abilities and masteries are identified where relevant; “classic UO” does not mean all those systems existed together.</p><table tabindex="0"><thead><tr><th>Familiar UO idea</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Skill-based characters and 7×GM templates</td><td>Keep skill-based characters; useful builds need not follow a single 7×GM recipe</td></tr><tr><td>A roughly 700-point skill budget, with era-dependent limits</td><td>Retain roughly 700 as the design direction, with meaningful trade-offs</td></tr><tr><td>Automatic weapon swings</td><td>Keep <a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Legacy</a>; <a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Modern</a> lets you choose when to commit to an action</td></tr><tr><td>Special weapon effects and, in later UO, selectable abilities</td><td>Learn <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attacks</a> and develop <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> with the options you use</td></tr><tr><td>Dedicated crafting characters as a common play style</td><td>Make professions useful on adventures as well as in workshops and trade</td></tr><tr><td>A spellbook containing spells you can cast</td><td>Separate permanent knowledge, practice and prepared <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Active Memory</a></td></tr><tr><td>Loot risk in Felucca-style play</td><td>Keep meaningful equipment risk; learned knowledge survives death, with item exceptions still to be resolved</td></tr><tr><td>Resource harvesting and established world objects</td><td>Let suitable trees, materials and terrain change routes and conflict</td></tr><tr><td>Exceptional craftsmanship and valuable equipment</td><td>Give quality <a href="/Syrolands-Public/en/guide/glossary.html#handling">handling</a>, <a href="/Syrolands-Public/en/guide/glossary.html#consistency">consistency</a>, integrity, traits and a history; <a href="/Syrolands-Public/en/guide/items/item-quality.html">Masterworks</a> remain rare</td></tr></tbody></table><h2 id="a-living-sandbox" tabindex="-1">A living sandbox <a class="header-anchor" href="#a-living-sandbox" aria-label="Permalink to &quot;A living sandbox&quot;">​</a></h2><p>A tree can become more than a source of logs: felling it could block a narrow path, open a route or change a defensive position. Materials, weather and tools should help you read the possibilities. Protected places and recovery rules still need limits; this is not a promise that every object can be destroyed.</p><h2 id="fight-don-t-just-watch-your-character-fight" tabindex="-1">Fight, don&#39;t just watch your character fight <a class="header-anchor" href="#fight-don-t-just-watch-your-character-fight" aria-label="Permalink to &quot;Fight, don&#39;t just watch your character fight&quot;">​</a></h2><p>Modern Combat is the preferred experimental direction: decide when to act, judge <a href="/Syrolands-Public/en/guide/combat/reach-and-spacing.html">reach</a> and leave room to recover. Legacy automatic cadence remains a supported alternative. <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Stamina</a>, Special Attacks, <a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a>, limb condition and equipment create choices; Anatomy and other information skills help you read them. Good timing and character expertise both matter.</p><h2 id="learn-the-world-instead-of-following-a-fixed-build" tabindex="-1">Learn the world instead of following a fixed build <a class="header-anchor" href="#learn-the-world-instead-of-following-a-fixed-build" aria-label="Permalink to &quot;Learn the world instead of following a fixed build&quot;">​</a></h2><p>A trainer, book, ruin or unfamiliar culture may teach you something a skill total cannot. Skill is capability; <a href="/Syrolands-Public/en/guide/characters/techniques.html">Technique</a> is a learned option; Familiarity is practiced fluency; <a href="/Syrolands-Public/en/guide/glossary.html#mastery">Mastery</a> is deeper expertise. You can specialize without expecting a maximum skill score to reveal every discovery.</p><h2 id="professions-are-part-of-your-character-not-an-alt" tabindex="-1">Professions are part of your character, not an alt <a class="header-anchor" href="#professions-are-part-of-your-character-not-an-alt" aria-label="Permalink to &quot;Professions are part of your character, not an alt&quot;">​</a></h2><p>Bring Cooking to an expedition, Alchemy to a difficult encounter, or Blacksmithing to damaged equipment. Tailoring, Carpentry and Tinkering also have uses beyond selling finished goods. Interactive craft, techniques, experimentation and reputation should make an adventurer&#39;s profession part of their identity, without forbidding dedicated crafters.</p><h2 id="magic-is-knowledge-you-prepare-and-practice" tabindex="-1">Magic is knowledge you prepare and practice <a class="header-anchor" href="#magic-is-knowledge-you-prepare-and-practice" aria-label="Permalink to &quot;Magic is knowledge you prepare and practice&quot;">​</a></h2><p>Learn a <a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Core Pattern</a>, practice it and choose which patterns to keep in Active Memory. A prepared spell still needs to be cast. Spellbooks, scrolls and reagents offer different ways to carry, consult and use magical knowledge; Inscription preserves and modifies it.</p><h2 id="objects-have-history-and-identity" tabindex="-1">Objects have history and identity <a class="header-anchor" href="#objects-have-history-and-identity" aria-label="Permalink to &quot;Objects have history and identity&quot;">​</a></h2><p>A dependable tool or well-balanced weapon can matter without simply adding damage. Handling, consistency and retained condition shape its usefulness. <a href="/Syrolands-Public/en/guide/items/item-quality.html">Masterworks</a> represent rare craft achievements; <a href="/Syrolands-Public/en/guide/items/item-quality.html">latent properties</a> are possible discoveries, not a promise that every exceptional item becomes magical.</p><h2 id="there-is-no-single-endgame" tabindex="-1">There is no single endgame <a class="header-anchor" href="#there-is-no-single-endgame" aria-label="Permalink to &quot;There is no single endgame&quot;">​</a></h2><p>Become known as a duelist, explorer, specialist crafter, trusted supplier or community organizer. Knowledge, economic relationships, social influence and reputation can be goals in their own right.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You take Carpentry on a woodland expedition. A blocked crossing becomes a problem your tools and knowledge might help solve, while a companion watches the approach. Your profession contributes to the same adventure as your combat choices.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/glossary.html">Glossary</a> · <a href="/Syrolands-Public/en/guide/">Player Guide</a> · <a href="/Syrolands-Public/en/guide/combat/overview.html">Combat</a> · <a href="/Syrolands-Public/en/guide/world/living-world.html">Living World</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/vision.html">Design Specs: project vision</a></p>',29)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
